/* ============================ VISUAL ATOMS ============================ */

function GlossSwatch({ hex, light, size = 56, ring = false, selected = false }) {
  return (
    <div
      style={{
        width: size, height: size, borderRadius: "9999px", position: "relative",
        background: `radial-gradient(circle at 32% 28%, ${light} 0%, ${hex} 55%, ${hex} 100%)`,
        boxShadow: selected
          ? `0 0 0 3px var(--tango-bg), 0 0 0 5px var(--tango-berry), 0 6px 14px rgba(58,38,32,0.25)`
          : ring
          ? `0 0 0 2px var(--tango-bg), 0 0 0 3px var(--tango-line), 0 4px 10px rgba(58,38,32,0.15)`
          : "0 4px 10px rgba(58,38,32,0.18)",
        flexShrink: 0,
      }}
    >
      <div
        style={{
          position: "absolute", top: "12%", left: "18%", width: "38%", height: "22%",
          borderRadius: "9999px", background: "rgba(255,255,255,0.55)", filter: "blur(1.5px)",
          transform: "rotate(-18deg)",
        }}
      />
    </div>
  );
}

function GlossTube({ hex, light, size = 140 }) {
  const w = size * 0.46;
  const h = size;
  const uid = hex.replace("#", "");
  return (
    <div style={{ width: w, height: h, position: "relative" }} className="tango-tube">
      <svg width={w} height={h} viewBox="0 0 64 140" style={{ overflow: "visible" }}>
        <defs>
          <linearGradient id={`body-${uid}`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor={light} />
            <stop offset="45%" stopColor={hex} />
            <stop offset="100%" stopColor={hex} />
          </linearGradient>
          <linearGradient id={`cap-${uid}`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="#8C6A2E" />
            <stop offset="18%" stopColor="#E8CE86" />
            <stop offset="38%" stopColor="#F6E7B8" />
            <stop offset="55%" stopColor="#CBA24E" />
            <stop offset="80%" stopColor="#9B7530" />
            <stop offset="100%" stopColor="#B8903F" />
          </linearGradient>
        </defs>
        {/* wand cap - metallic gold */}
        <rect x="14" y="0" width="36" height="34" rx="7" fill={`url(#cap-${uid})`} stroke="#7A5B24" strokeWidth="0.5" />
        <rect x="14" y="27" width="36" height="4" fill="#7A5B24" opacity="0.35" />
        {/* neck */}
        <rect x="26" y="32" width="12" height="14" fill="#8C6A2E" opacity="0.8" />
        {/* glass body */}
        <rect x="6" y="46" width="52" height="92" rx="16" fill={`url(#body-${uid})`} stroke="rgba(58,38,32,0.15)" />
        {/* vertical TANGIO label */}
        <text
          x="32" y="98" textAnchor="middle"
          transform="rotate(-90 32 98)"
          fontFamily="Inter, sans-serif" fontWeight="600" fontSize="7.5" letterSpacing="2.5"
          fill="#B8903F" opacity="0.8"
        >TANGIO</text>
        {/* shine streak */}
        <rect x="14" y="54" width="7" height="76" rx="4" fill="white" opacity="0.3" transform="skewX(-8)" />
        <rect x="46" y="60" width="3" height="60" rx="2" fill="white" opacity="0.18" transform="skewX(-8)" />
        {/* base */}
        <rect x="6" y="126" width="52" height="12" rx="6" fill="#2C1E19" opacity="0.4" />
      </svg>
      <div className="tango-shine-sweep" />
    </div>
  );
}

function StarRow({ rating, size = 14, showNumber = true, reviews }) {
  const full = Math.round(rating);
  return (
    <div className="flex items-center gap-1">
      <div className="flex items-center" style={{ gap: 2 }}>
        {[1, 2, 3, 4, 5].map((i) => (
          <Star
            key={i}
            size={size}
            fill={i <= full ? "var(--tango-gold)" : "none"}
            color={i <= full ? "var(--tango-gold)" : "var(--tango-line)"}
            strokeWidth={1.5}
          />
        ))}
      </div>
      {showNumber && (
        <span style={{ fontSize: 12.5, color: "var(--tango-ink-soft)" }}>
          {rating}{reviews ? ` (${reviews})` : ""}
        </span>
      )}
    </div>
  );
}

function Eyebrow({ children }) {
  return (
    <div className="flex items-center gap-3 mb-3">
      <span style={{ width: 22, height: 1, background: "var(--tango-gold)" }} />
      <span style={{ fontFamily: "Inter", fontSize: 12, letterSpacing: "0.22em", textTransform: "uppercase", color: "var(--tango-berry-dark)", fontWeight: 600 }}>
        {children}
      </span>
    </div>
  );
}

function Pill({ children, active, onClick }) {
  return (
    <button
      onClick={onClick}
      className="px-4 py-2 rounded-full text-sm transition-all"
      style={{
        border: `1px solid ${active ? "var(--tango-berry)" : "var(--tango-line)"}`,
        background: active ? "var(--tango-berry)" : "transparent",
        color: active ? "#fff" : "var(--tango-ink)",
        fontFamily: "Inter", fontWeight: 500, whiteSpace: "nowrap",
      }}
    >
      {children}
    </button>
  );
}

function Badge({ children, tone = "berry" }) {
  const tones = {
    berry: { bg: "var(--tango-berry)", fg: "#fff" },
    gold: { bg: "var(--tango-gold)", fg: "#fff" },
    line: { bg: "var(--tango-blush)", fg: "var(--tango-ink)" },
  };
  const t = tones[tone];
  return (
    <span
      style={{
        background: t.bg, color: t.fg, fontFamily: "Inter", fontWeight: 600, fontSize: 11,
        letterSpacing: "0.05em", padding: "4px 10px", borderRadius: 999, textTransform: "uppercase",
        display: "inline-block",
      }}
    >
      {children}
    </span>
  );
}

/* ============================== APP ============================== */

export default function TangioApp() {
  const [page, setPage] = useState("home");
  const [activeShadeId, setActiveShadeId] = useState(SHADES[0].id);
  const [cart, setCart] = useState([]); // {id, qty}
  const [wishlist, setWishlist] = useState([]);
  const [recentlyViewed, setRecentlyViewed] = useState([]);
  const [user, setUser] = useState(null);
  const [orders, setOrders] = useState([]);
  const [toast, setToast] = useState(null);
  const [mobileNav, setMobileNav] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [showLogin, setShowLogin] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [chatOpen, setChatOpen] = useState(false);
  const [couponCode, setCouponCode] = useState("");
  const [appliedCoupon, setAppliedCoupon] = useState(null);
  const [checkoutStep, setCheckoutStep] = useState(1);
  const [address, setAddress] = useState({ name: "", phone: "", line: "", city: "", state: "", pin: "" });
  const [deliveryMethod, setDeliveryMethod] = useState("standard");
  const [paymentMethod, setPaymentMethod] = useState("upi");
  const [points, setPoints] = useState(120);
  const [lastOrder, setLastOrder] = useState(null);
  const [reviewsState, setReviewsState] = useState(REVIEWS.map((r, i) => ({ ...r, id: i, helpful: Math.floor(Math.random() * 40) + 3, approved: true })));

  const go = (p, shadeId) => {
    if (shadeId) {
      setActiveShadeId(shadeId);
      setRecentlyViewed((rv) => [shadeId, ...rv.filter((x) => x !== shadeId)].slice(0, 6));
    }
    setPage(p);
    setMobileNav(false);
    window.scrollTo({ top: 0, behavior: "instant" });
  };

  const notify = (msg) => {
    setToast(msg);
    window.clearTimeout(notify._t);
    notify._t = window.setTimeout(() => setToast(null), 2400);
  };

  const addToCart = (id, qty = 1) => {
    setCart((c) => {
      const existing = c.find((i) => i.id === id);
      if (existing) return c.map((i) => (i.id === id ? { ...i, qty: i.qty + qty } : i));
      return [...c, { id, qty }];
    });
    notify(`${shadeById(id).name} added to bag`);
  };
  const removeFromCart = (id) => setCart((c) => c.filter((i) => i.id !== id));
  const setQty = (id, qty) => setCart((c) => c.map((i) => (i.id === id ? { ...i, qty: Math.max(1, qty) } : i)));
  const toggleWishlist = (id) => {
    setWishlist((w) => (w.includes(id) ? w.filter((x) => x !== id) : [...w, id]));
    notify(wishlist.includes(id) ? "Removed from wishlist" : "Saved to wishlist");
  };

  const cartDetailed = cart.map((i) => ({ ...i, shade: shadeById(i.id) }));
  const subtotal = cartDetailed.reduce((s, i) => s + i.shade.price * i.qty, 0);
  const mrpTotal = cartDetailed.reduce((s, i) => s + i.shade.mrp * i.qty, 0);
  const discount = mrpTotal - subtotal;
  const shipping = deliveryMethod === "express" ? 149 : subtotal >= 599 || subtotal === 0 ? 0 : 49;
  const couponDiscount = appliedCoupon ? Math.round(subtotal * appliedCoupon.pct) : 0;
  const total = Math.max(0, subtotal - couponDiscount) + shipping;

  const applyCoupon = () => {
    const code = couponCode.trim().toUpperCase();
    const table = {
      TANGIO10: { pct: 0.1, label: "10% off your first order" },
      SHINE20: { pct: 0.2, label: "20% limited-time shine sale" },
      GLOW15: { pct: 0.15, label: "15% off glow-up combo" },
    };
    if (table[code]) {
      setAppliedCoupon({ code, ...table[code] });
      notify(`Coupon ${code} applied`);
    } else {
      notify("That coupon code is not valid");
    }
  };

  const placeOrder = () => {
    const id = "TG" + Math.floor(100000 + Math.random() * 900000);
    const order = {
      id, date: new Date().toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" }),
      items: cartDetailed.map((i) => ({ name: i.shade.name, qty: i.qty, price: i.shade.price, hex: i.shade.hex, light: i.shade.light })),
      total, address, deliveryMethod, paymentMethod,
      status: "Order Placed",
      eta: deliveryMethod === "express" ? "1-2 business days" : "4-6 business days",
    };
    setOrders((o) => [order, ...o]);
    setLastOrder(order);
    setPoints((p) => p + Math.round(total / 20));
    setCart([]);
    setAppliedCoupon(null);
    setCheckoutStep(4);
  };

  const login = (name, email) => {
    setUser({ name, email });
    setShowLogin(false);
    notify(`Welcome back, ${name.split(" ")[0]}`);
  };
  const logout = () => {
    setUser(null);
    go("home");
  };

  const searchResults = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return [];
    return SHADES.filter(
      (s) => s.name.toLowerCase().includes(q) || s.finish.toLowerCase().includes(q) || (s.tags || []).some((t) => t.toLowerCase().includes(q))
    );
  }, [searchQuery]);

  return (
    <div style={{ background: "var(--tango-bg)", minHeight: "100vh", fontFamily: "Inter, sans-serif", color: "var(--tango-ink)" }}>
      <GlobalStyle />
      <TopBanner />
      <Nav
        page={page} go={go} user={user}
        cartCount={cart.reduce((s, i) => s + i.qty, 0)}
        wishlistCount={wishlist.length}
        mobileNav={mobileNav} setMobileNav={setMobileNav}
        searchOpen={searchOpen} setSearchOpen={setSearchOpen}
        setShowLogin={setShowLogin}
      />

      {searchOpen && (
        <SearchOverlay
          query={searchQuery} setQuery={setSearchQuery} results={searchResults}
          onSelect={(id) => { setSearchOpen(false); setSearchQuery(""); go("product", id); }}
          onClose={() => { setSearchOpen(false); setSearchQuery(""); }}
        />
      )}

      <main>
        {page === "home" && (
          <HomePage go={go} addToCart={addToCart} toggleWishlist={toggleWishlist} wishlist={wishlist}
            setShowQuiz={setShowQuiz} />
        )}
        {page === "shop" && (
          <ShopPage go={go} addToCart={addToCart} toggleWishlist={toggleWishlist} wishlist={wishlist} initialShade={activeShadeId} />
        )}
        {page === "shades" && (
          <ShadeExplorerPage go={go} addToCart={addToCart} />
        )}
        {page === "product" && (
          <ProductPage
            shadeId={activeShadeId} setShadeId={(id) => go("product", id)} addToCart={addToCart}
            toggleWishlist={toggleWishlist} wishlist={wishlist} go={go}
            reviewsState={reviewsState} setReviewsState={setReviewsState}
            recentlyViewed={recentlyViewed}
          />
        )}
        {page === "cart" && (
          <CartPage
            cartDetailed={cartDetailed} setQty={setQty} removeFromCart={removeFromCart}
            subtotal={subtotal} discount={discount} shipping={shipping} total={total}
            couponCode={couponCode} setCouponCode={setCouponCode} applyCoupon={applyCoupon}
            appliedCoupon={appliedCoupon} couponDiscount={couponDiscount} go={go}
          />
        )}
        {page === "wishlist" && (
          <WishlistPage wishlist={wishlist} addToCart={addToCart} toggleWishlist={toggleWishlist} go={go} />
        )}
        {page === "checkout" && (
          <CheckoutPage
            step={checkoutStep} setStep={setCheckoutStep} address={address} setAddress={setAddress}
            deliveryMethod={deliveryMethod} setDeliveryMethod={setDeliveryMethod}
            paymentMethod={paymentMethod} setPaymentMethod={setPaymentMethod}
            cartDetailed={cartDetailed} subtotal={subtotal} shipping={shipping} total={total}
            couponDiscount={couponDiscount} placeOrder={placeOrder} lastOrder={lastOrder} go={go}
            user={user} setShowLogin={setShowLogin}
          />
        )}
        {page === "orders" && <OrdersPage orders={orders} go={go} />}
        {page === "profile" && (
          <ProfilePage user={user} orders={orders} wishlist={wishlist} points={points} go={go} logout={logout} recentlyViewed={recentlyViewed} />
        )}
        {page === "offers" && <OffersPage go={go} />}
        {page === "about" && <AboutPage go={go} />}
        {page === "contact" && <ContactPage notify={notify} />}
        {page === "faq" && <FaqPage />}
        {page === "admin" && <AdminPage orders={orders} reviewsState={reviewsState} setReviewsState={setReviewsState} />}
      </main>

      <Footer go={go} />

      <ChatWidget open={chatOpen} setOpen={setChatOpen} go={go} />
      {showQuiz && <ShadeQuizModal onClose={() => setShowQuiz(false)} onView={(id) => { setShowQuiz(false); go("product", id); }} addToCart={addToCart} />}
      {showLogin && <LoginModal onClose={() => setShowLogin(false)} onLogin={login} />}
      {toast && <div className="tango-toast">{toast}</div>}
    </div>
  );
}

/* ============================ GLOBAL STYLE ============================ */

function GlobalStyle() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,340;0,9..144,480;0,9..144,600;1,9..144,480;1,9..144,600&family=Inter:wght@400;500;600;700;800&display=swap');

      :root {
        --tango-bg: #FBF3F0;
        --tango-ink: #3A2620;
        --tango-ink-soft: #7A6259;
        --tango-berry: #B23A55;
        --tango-berry-dark: #8C2C42;
        --tango-gold: #C9962C;
        --tango-blush: #F0DCD9;
        --tango-latte: #E9D8C8;
        --tango-line: rgba(58,38,32,0.14);
        --tango-card: #FFFDFB;
      }
      * { box-sizing: border-box; }
      body { margin: 0; }
      .tango-serif { font-family: 'Fraunces', serif; }
      ::selection { background: var(--tango-berry); color: #fff; }
      ::-webkit-scrollbar { width: 10px; height: 10px; }
      ::-webkit-scrollbar-thumb { background: var(--tango-blush); border-radius: 999px; }
      ::-webkit-scrollbar-track { background: transparent; }
      a, button { cursor: pointer; }
      button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible {
        outline: 2px solid var(--tango-berry); outline-offset: 2px;
      }
      @media (prefers-reduced-motion: reduce) {
        * { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
      }

      @keyframes tangoFadeUp { from { opacity: 0; transform: translateY(14px);} to { opacity: 1; transform: translateY(0);} }
      .tango-fade-up { animation: tangoFadeUp 0.7s ease both; }

      @keyframes tangoShine { 0% { transform: translateX(-140%) rotate(10deg);} 60%,100% { transform: translateX(260%) rotate(10deg);} }
      .tango-shine-sweep {
        position: absolute; top: -20%; left: 0; width: 26%; height: 140%;
        background: linear-gradient(100deg, transparent, rgba(255,255,255,0.55), transparent);
        pointer-events: none; opacity: 0;
      }
      .tango-tube:hover .tango-shine-sweep, .tango-card:hover .tango-shine-sweep {
        animation: tangoShine 1.1s ease;
        opacity: 1;
      }
      .tango-card { position: relative; overflow: hidden; }

      @keyframes tangoPulseRing {
        0% { box-shadow: 0 0 0 0 rgba(178,58,85,0.35); }
        100% { box-shadow: 0 0 0 14px rgba(178,58,85,0); }
      }
      .tango-pulse { animation: tangoPulseRing 2.2s ease-out infinite; }

      .tango-btn-primary {
        background: var(--tango-berry); color: #fff; border: none; font-weight: 600;
        border-radius: 999px; padding: 13px 28px; font-family: 'Inter'; font-size: 14.5px;
        transition: background 0.2s ease, transform 0.15s ease; letter-spacing: 0.01em;
      }
      .tango-btn-primary:hover { background: var(--tango-berry-dark); transform: translateY(-1px); }
      .tango-btn-outline {
        background: transparent; color: var(--tango-ink); border: 1.5px solid var(--tango-ink);
        font-weight: 600; border-radius: 999px; padding: 12px 26px; font-family: 'Inter'; font-size: 14.5px;
        transition: all 0.2s ease;
      }
      .tango-btn-outline:hover { background: var(--tango-ink); color: #fff; }
      .tango-btn-gold {
        background: var(--tango-gold); color: #fff; border: none; font-weight: 600;
        border-radius: 999px; padding: 13px 28px; font-family: 'Inter'; font-size: 14.5px;
      }

      .tango-toast {
        position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
        background: var(--tango-ink); color: #fff; padding: 12px 22px; border-radius: 999px;
        font-size: 14px; z-index: 200; box-shadow: 0 8px 24px rgba(0,0,0,0.25);
        animation: tangoFadeUp 0.25s ease both;
      }

      input, textarea, select {
        font-family: 'Inter'; border-radius: 12px; border: 1.5px solid var(--tango-line);
        padding: 11px 14px; background: #fff; color: var(--tango-ink); font-size: 14.5px; width: 100%;
      }
      input:focus, textarea:focus, select:focus { border-color: var(--tango-berry); }
      label { font-size: 12.5px; font-weight: 600; color: var(--tango-ink-soft); display:block; margin-bottom: 6px; letter-spacing: 0.01em; }
    `}</style>
  );
}

/* ============================ TOP BANNER + NAV ============================ */

function TopBanner() {
  return (
    <div style={{ background: "var(--tango-ink)", color: "#fff", textAlign: "center", fontSize: 12.5, padding: "8px 12px", letterSpacing: "0.04em" }}>
      Vegan &middot; Organic &middot; Home-Grown &mdash; Free shipping over &#8377;599 &middot; Shine Your Way
    </div>
  );
}

function NavLink({ children, onClick, active }) {
  return (
    <button
      onClick={onClick}
      style={{
        fontFamily: "Inter", fontSize: 14, fontWeight: 500, color: active ? "var(--tango-berry-dark)" : "var(--tango-ink)",
        background: "none", border: "none", padding: "6px 2px", position: "relative",
      }}
    >
      {children}
      {active && <span style={{ position: "absolute", left: 0, right: 0, bottom: -2, height: 2, background: "var(--tango-berry)", borderRadius: 2 }} />}
    </button>
  );
}

function Nav({ page, go, user, cartCount, wishlistCount, mobileNav, setMobileNav, searchOpen, setSearchOpen, setShowLogin }) {
  const links = [
    ["home", "Home"], ["shop", "Shop"], ["shades", "Shades"], ["about", "About Us"],
    ["offers", "Offers"], ["contact", "Contact"],
  ];
  return (
    <header style={{ position: "sticky", top: 0, zIndex: 100, background: "rgba(251,243,240,0.92)", backdropFilter: "blur(8px)", borderBottom: "1px solid var(--tango-line)" }}>
      <div className="flex items-center justify-between" style={{ maxWidth: 1280, margin: "0 auto", padding: "14px 20px" }}>
        <button className="md:hidden" onClick={() => setMobileNav(true)} aria-label="Open menu">
          <Menu size={22} />
        </button>

        <button onClick={() => go("home")} className="flex flex-col items-center" style={{ background: "none", border: "none" }}>
          <span className="tango-serif" style={{ fontSize: 26, fontWeight: 600, letterSpacing: "0.03em", color: "var(--tango-berry-dark)", fontStyle: "italic", lineHeight: 1 }}>
            Tangio
          </span>
          <span style={{ fontSize: 9, letterSpacing: "0.24em", textTransform: "uppercase", color: "var(--tango-ink-soft)", marginTop: 1 }}>Shine Your Way</span>
        </button>

        <nav className="hidden md:flex items-center" style={{ gap: 26 }}>
          {links.map(([p, label]) => (
            <NavLink key={p} onClick={() => go(p)} active={page === p}>{label}</NavLink>
          ))}
        </nav>

        <div className="flex items-center" style={{ gap: 14 }}>
          <button onClick={() => setSearchOpen(!searchOpen)} aria-label="Search"><Search size={20} /></button>
          <button onClick={() => go("wishlist")} aria-label="Wishlist" style={{ position: "relative" }}>
            <Heart size={20} />
            {wishlistCount > 0 && <CountDot n={wishlistCount} />}
          </button>
          <button onClick={() => go("cart")} aria-label="Cart" style={{ position: "relative" }}>
            <ShoppingBag size={20} />
            {cartCount > 0 && <CountDot n={cartCount} />}
          </button>
          <button onClick={() => (user ? go("profile") : setShowLogin(true))} aria-label="Account">
            <User size={20} />
          </button>
        </div>
      </div>

      {mobileNav && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(58,38,32,0.4)", zIndex: 150 }} onClick={() => setMobileNav(false)}>
          <div
            onClick={(e) => e.stopPropagation()}
            style={{ background: "var(--tango-bg)", width: 280, height: "100%", padding: 24, boxShadow: "8px 0 24px rgba(0,0,0,0.2)" }}
            className="tango-fade-up"
          >
            <div className="flex items-center justify-between" style={{ marginBottom: 28 }}>
              <span className="tango-serif" style={{ fontSize: 22, fontStyle: "italic", color: "var(--tango-berry-dark)" }}>Tangio</span>
              <button onClick={() => setMobileNav(false)}><X size={22} /></button>
            </div>
            <div className="flex flex-col" style={{ gap: 18 }}>
              {[...links, ["best-sellers-anchor", "Best Sellers"]].map(([p, label]) => (
                <button key={label} onClick={() => go(p === "best-sellers-anchor" ? "home" : p)} style={{ textAlign: "left", background: "none", border: "none", fontSize: 17, fontFamily: "Inter", fontWeight: 500 }}>
                  {label}
                </button>
              ))}
              <button onClick={() => go("faq")} style={{ textAlign: "left", background: "none", border: "none", fontSize: 17, fontFamily: "Inter", fontWeight: 500 }}>FAQ</button>
            </div>
          </div>
        </div>
      )}
    </header>
  );
}

function CountDot({ n }) {
  return (
    <span style={{
      position: "absolute", top: -7, right: -9, background: "var(--tango-berry)", color: "#fff",
      fontSize: 10, fontWeight: 700, borderRadius: 999, minWidth: 16, height: 16, display: "flex",
      alignItems: "center", justifyContent: "center", padding: "0 3px",
    }}>{n}</span>
  );
}

function SearchOverlay({ query, setQuery, results, onSelect, onClose }) {
  return (
    <div style={{ background: "var(--tango-card)", borderBottom: "1px solid var(--tango-line)", position: "sticky", top: 65, zIndex: 90 }}>
      <div style={{ maxWidth: 720, margin: "0 auto", padding: "18px 20px" }}>
        <div className="flex items-center" style={{ gap: 10 }}>
          <Search size={18} color="var(--tango-ink-soft)" />
          <input autoFocus placeholder="Search shades, finishes, moods... try Raspberry" value={query} onChange={(e) => setQuery(e.target.value)} style={{ border: "none", padding: "8px 0" }} />
          {query && <button onClick={() => setQuery("")}><X size={16} /></button>}
          <button onClick={onClose} style={{ fontSize: 13, color: "var(--tango-ink-soft)", background: "none", border: "none" }}>Close</button>
        </div>
        {query && (
          <div style={{ marginTop: 12 }}>
            {results.length === 0 ? (
              <p style={{ fontSize: 14, color: "var(--tango-ink-soft)" }}>No shades match "{query}" &mdash; try a shade name like Bubble Pop or Espresso.</p>
            ) : (
              <div className="flex flex-col" style={{ gap: 4 }}>
                {results.map((s) => (
                  <button key={s.id} onClick={() => onSelect(s.id)} className="flex items-center" style={{ gap: 12, background: "none", border: "none", padding: "8px 6px", textAlign: "left", borderRadius: 10 }}>
                    <GlossSwatch hex={s.hex} light={s.light} size={30} />
                    <div>
                      <div style={{ fontSize: 14.5, fontWeight: 600 }}>{s.name}</div>
                      <div style={{ fontSize: 12.5, color: "var(--tango-ink-soft)" }}>{s.finish} &middot; {money(s.price)}</div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

