/* ============================ AI SHADE QUIZ ============================ */

function ShadeQuizModal({ onClose, onView, addToCart }) {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState({ tone: "", undertone: "", color: "", occasion: "" });
  const questions = [
    { key: "tone", label: "What is your skin tone?", options: ["Fair", "Medium", "Deep"] },
    { key: "undertone", label: "What is your undertone?", options: ["Warm", "Cool", "Neutral"] },
    { key: "color", label: "Preferred color family?", options: ["Nude", "Pink/Berry", "Shimmer/Gold"] },
    { key: "occasion", label: "Desired look?", options: ["Everyday", "Party/Night", "Your-Lips-But-Better"] },
  ];

  const recommend = () => {
    let picks = [];
    if (answers.color === "Nude") picks.push(answers.undertone === "Warm" ? "espresso" : "iced-latte");
    if (answers.color === "Pink/Berry") picks.push(answers.occasion === "Party/Night" ? "bubble-pop" : "raspberry");
    if (answers.color === "Shimmer/Gold") picks.push("gold-rush");
    if (answers.occasion === "Your-Lips-But-Better") picks.push("diet-coke");
    if (answers.undertone === "Warm" && !picks.includes("caramel-toffee")) picks.push("caramel-toffee");
    picks = [...new Set(picks)].slice(0, 2);
    if (picks.length === 0) picks = ["raspberry", "iced-latte"];
    return picks.map(shadeById);
  };

  const done = step === questions.length;

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(58,38,32,0.45)", zIndex: 400, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{ background: "var(--tango-card)", borderRadius: 24, padding: 32, maxWidth: 480, width: "100%", position: "relative" }}>
        <button onClick={onClose} style={{ position: "absolute", top: 16, right: 16, background: "none", border: "none" }}><X size={20} /></button>
        <div className="flex items-center" style={{ gap: 8, marginBottom: 4 }}>
          <Sparkles size={18} color="var(--tango-berry-dark)" />
          <span style={{ fontWeight: 700, fontSize: 13, letterSpacing: "0.04em", color: "var(--tango-berry-dark)", textTransform: "uppercase" }}>Find Your Perfect Shade</span>
        </div>

        {!done ? (
          <div style={{ marginTop: 16 }}>
            <h3 className="tango-serif" style={{ margin: "0 0 18px" }}>{questions[step].label}</h3>
            <div className="flex flex-col" style={{ gap: 10 }}>
              {questions[step].options.map((o) => (
                <button key={o} onClick={() => { setAnswers({ ...answers, [questions[step].key]: o }); setStep(step + 1); }}
                  className="tango-btn-outline" style={{ textAlign: "left" }}>
                  {o}
                </button>
              ))}
            </div>
            <div style={{ marginTop: 18, fontSize: 12, color: "var(--tango-ink-soft)" }}>Question {step + 1} of {questions.length}</div>
          </div>
        ) : (
          <div style={{ marginTop: 16 }}>
            <h3 className="tango-serif" style={{ margin: "0 0 6px" }}>Your Tangio Match</h3>
            <p style={{ fontSize: 13.5, color: "var(--tango-ink-soft)", marginBottom: 18 }}>
              Based on your preferences, we recommend {recommend().map((s) => s.name).join(" and ")}.
            </p>
            <div className="flex flex-col" style={{ gap: 14 }}>
              {recommend().map((s) => (
                <div key={s.id} className="flex items-center" style={{ gap: 14, border: "1px solid var(--tango-line)", borderRadius: 16, padding: 14 }}>
                  <GlossSwatch hex={s.hex} light={s.light} size={44} />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 700, fontSize: 15 }}>{s.name}</div>
                    <div style={{ fontSize: 12, color: "var(--tango-ink-soft)" }}>{s.look} &middot; {s.finish}</div>
                  </div>
                  <button className="tango-btn-primary" style={{ fontSize: 12.5, padding: "8px 14px" }} onClick={() => addToCart(s.id)}>Add</button>
                </div>
              ))}
            </div>
            <div className="flex" style={{ gap: 10, marginTop: 20 }}>
              <button className="tango-btn-outline" style={{ flex: 1 }} onClick={() => { setStep(0); setAnswers({ tone: "", undertone: "", color: "", occasion: "" }); }}>Retake Quiz</button>
              <button className="tango-btn-primary" style={{ flex: 1 }} onClick={() => onView(recommend()[0].id)}>View Shade</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* ============================ AI BEAUTY ASSISTANT ============================ */

function answerBeautyBot(msg) {
  const q = msg.toLowerCase();
  const nudes = SHADES.filter((s) => s.tags?.includes("Nude")).map((s) => s.name).join(" and ");
  const party = SHADES.filter((s) => s.tags?.includes("Party")).map((s) => s.name).join(", ");
  const everyday = SHADES.filter((s) => s.tags?.includes("Everyday")).map((s) => s.name).join(", ");

  if (q.includes("nude")) return `Our nude shades are ${nudes}. Espresso is a deeper nude, Iced Latte is a softer everyday nude.`;
  if (q.includes("party") || q.includes("night") || q.includes("wedding")) return `For a party or night out, reach for ${party} - Gold Rush especially catches the light beautifully.`;
  if (q.includes("everyday") || q.includes("daily") || q.includes("work")) return `For everyday wear, try ${everyday} - they are all comfortable, buildable and low-maintenance.`;
  if (q.includes("ingredient")) return "Every Tangio shade is made with organic jojoba oil, shea butter, vegan candelilla wax and vitamin E - no parabens, sulfates or animal-derived ingredients.";
  if (q.includes("differ") || q.includes("different") || q.includes("why tango")) return "Tangio is vegan, organic and home-grown, with a lightweight formula and a mirror-glass shine that never turns sticky.";
  if (q.includes("natural")) return "For the most natural look, Diet Coke gives a your-lips-but-better tint, and Iced Latte adds soft warmth without much color payoff.";
  if (q.includes("bold") || q.includes("statement")) return "Raspberry and Bubble Pop are our boldest, most pigmented shades if you want a statement lip.";
  if (q.includes("shade") && q.includes("choose")) return "Try our Find Your Perfect Shade quiz on the homepage, or tell me your favorite color family and I can suggest a shade.";
  if (q.includes("vegan")) return "Yes, every single Tangio shade is 100% vegan.";
  if (q.includes("price") || q.includes("cost")) return "Every Tangio shade is priced at \u20B9320.";
  if (q.includes("hi") || q.includes("hello") || q.includes("hey")) return "Hi, I am the Tangio Beauty Assistant. Ask me which shade suits you, what is in our formula, or what makes Tangio different.";
  return "I can help with Tangio shades, ingredients and finding your perfect match - try asking which shade is best for everyday wear, or which shades are nude.";
}

function ChatWidget({ open, setOpen, go }) {
  const [messages, setMessages] = useState([{ from: "bot", text: "Hi, I am the Tangio Beauty Assistant. Which shade should I help you find today?" }]);
  const [input, setInput] = useState("");
  const endRef = useRef(null);

  useEffect(() => { endRef.current?.scrollIntoView({ behavior: "smooth" }); }, [messages, open]);

  const send = (e) => {
    e.preventDefault();
    if (!input.trim()) return;
    const userMsg = input;
    setMessages((m) => [...m, { from: "user", text: userMsg }]);
    setInput("");
    setTimeout(() => setMessages((m) => [...m, { from: "bot", text: answerBeautyBot(userMsg) }]), 400);
  };

  return (
    <>
      <button onClick={() => setOpen(!open)} className="tango-pulse" style={{
        position: "fixed", bottom: 24, right: 24, width: 56, height: 56, borderRadius: "50%",
        background: "var(--tango-berry)", color: "#fff", border: "none", display: "flex", alignItems: "center",
        justifyContent: "center", zIndex: 250, boxShadow: "0 8px 20px rgba(178,58,85,0.35)",
      }} aria-label="Tangio Beauty Assistant">
        {open ? <X size={22} /> : <MessageCircle size={22} />}
      </button>

      {open && (
        <div style={{
          position: "fixed", bottom: 92, right: 24, width: 320, maxWidth: "88vw", height: 420, background: "var(--tango-card)",
          borderRadius: 20, boxShadow: "0 16px 40px rgba(58,38,32,0.25)", zIndex: 250, display: "flex", flexDirection: "column", overflow: "hidden",
          border: "1px solid var(--tango-line)",
        }}>
          <div style={{ background: "var(--tango-ink)", color: "#fff", padding: "14px 16px" }}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>Tangio Beauty Assistant</div>
            <div style={{ fontSize: 11.5, opacity: 0.75 }}>Ask me about shades &amp; ingredients</div>
          </div>
          <div style={{ flex: 1, overflowY: "auto", padding: 14, display: "flex", flexDirection: "column", gap: 10 }}>
            {messages.map((m, i) => (
              <div key={i} style={{
                alignSelf: m.from === "bot" ? "flex-start" : "flex-end", background: m.from === "bot" ? "var(--tango-blush)" : "var(--tango-berry)",
                color: m.from === "bot" ? "var(--tango-ink)" : "#fff", padding: "9px 13px", borderRadius: 14, fontSize: 13, maxWidth: "85%", lineHeight: 1.5,
              }}>
                {m.text}
              </div>
            ))}
            <div ref={endRef} />
          </div>
          <form onSubmit={send} className="flex items-center" style={{ padding: 10, borderTop: "1px solid var(--tango-line)", gap: 8 }}>
            <input placeholder="Ask about a shade..." value={input} onChange={(e) => setInput(e.target.value)} style={{ padding: "9px 12px", fontSize: 13 }} />
            <button type="submit" style={{ background: "var(--tango-berry)", border: "none", borderRadius: "50%", width: 34, height: 34, display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", flexShrink: 0 }}><Send size={14} /></button>
          </form>
        </div>
      )}
    </>
  );
}

